import threading


class Pool:
    def __init__(self):
        self._lock = threading.Lock()
        self._free = []

    def acquire(self):
        with self._lock:
            return self._free.pop() if self._free else None

    def release(self, conn):
        with self._lock:
            self._free.append(conn)

